/**
 * A segmented time-of-day field with no popup (`design/components/time-input.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/time-input.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createMemo, createUniqueId, mergeProps, onCleanup, onMount, type JSX } from 'solid-js'

import {
  Each,
  agentMember,
  agentTime,
  claimSlot,
  createCell,
  createDerived,
  elementRef,
  eraseSegment,
  fieldSegments,
  itemOf,
  stepSegment,
  timeDraft,
  timeFieldValue,
  typeIntoSegment,
  watchEffect,
  type Defaults,
  type Time,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/controls/time-input.module.css'

export interface TimeInputMessages {
  empty: string
}

export interface TimeInputProps {
  'aria-describedby'?: string
  /**
   * Wired by FormField; set directly only when there is no visible label.
   */
  'aria-label'?: string
  'aria-labelledby'?: string
  'aria-required'?: boolean
  defaultValue?: Time | null
  disabled?: boolean
  /**
   * The segment list: `'minute'` is `[hh] [mm]`, and `'hour'` drops the minute segment. Seconds
   * are not offered, because no known screen edits them, and options are added only when needed.
   */
  granularity?: 'hour' | 'minute'
  /**
   * The locale decides by default, and this prop overrides it. `12` renders the dayPeriod
   * segment, and `24` never does.
   */
  hourCycle?: 12 | 24
  id?: string
  invalid?: boolean
  /**
   * Sets the segment order, the day period names and the separator.
   */
  locale?: string
  /**
   * Defaults to generic English (`Empty`). Localized hosts pass strings from their catalog.
   */
  messages?: TimeInputMessages
  /**
   * Serializes the ISO-8601 time in `Time`'s own format, such as `"09:30:00"`.
   */
  name?: string
  onChange?: (value: Time | null) => void
  /**
   * Keeps segments focusable and selectable, but arrows and digits do not edit.
   */
  readOnly?: boolean
  size?: 'sm' | 'md' | 'lg'
  /**
   * `@internationalized/date`'s `Time`: a plain time of day with no date and no time zone, never
   * a JS `Date` (Calendar's law). The field edits down to its granularity. Finer fields in a
   * supplied value (seconds on a `Time` the app built) are kept unchanged, never silently set to
   * zero.
   */
  value?: Time | null
}

/** A segmented time-of-day field with no popup. */
export default function TimeInput(given: TimeInputProps): JSX.Element {
  const props = mergeProps(
    {
      granularity: 'minute',
      size: 'md',
      disabled: false,
      readOnly: false,
      invalid: false,
    } as Defaults<TimeInputProps, 'granularity' | 'size' | 'disabled' | 'readOnly' | 'invalid'>,
    claimSlot(given, 'group'),
  )
  const uid = createUniqueId()
  const field = elementRef<HTMLElement>()
  const browserLanguage = createCell(undefined as string | undefined)
  const draft = createCell(
    timeDraft(props.value !== undefined ? props.value : props.defaultValue, {
      locale: props.locale ?? browserLanguage.value ?? 'en-US',
      parts: props.granularity === 'hour' ? (['hour'] as const) : (['hour', 'minute'] as const),
      hourCycle: props.hourCycle,
    }),
  )
  const typed = createCell('')
  const reported = createCell(
    (props.value !== undefined ? props.value : props.defaultValue)?.toString() ?? '',
  )
  const say = createDerived(() => props.messages ?? { empty: 'Empty' })
  const language = createDerived(() => props.locale ?? browserLanguage.value ?? 'en-US')
  const fieldOptions = createDerived(() => ({
    locale: language.value,
    parts: props.granularity === 'hour' ? (['hour'] as const) : (['hour', 'minute'] as const),
    hourCycle: props.hourCycle,
  }))
  const segments = createDerived(() => fieldSegments(draft.value, fieldOptions.value))
  const kept = createDerived(
    () => (props.value !== undefined ? props.value : props.defaultValue) ?? null,
  )
  const current = createDerived(() => timeFieldValue(draft.value, fieldOptions.value, kept.value))
  const commit = createDerived(() => (next: ReturnType<typeof timeDraft>): void => {
    draft.value = next
    const after = timeFieldValue(next, fieldOptions.value, kept.value)
    const text = after?.toString() ?? ''
    if (text !== reported.value) {
      reported.value = text
      props.onChange?.(after)
    }
  })
  const segmentName = createDerived(() => (type: string): string => {
    try {
      return new Intl.DisplayNames(language.value, { type: 'dateTimeField' }).of(type) ?? type
    } catch {
      return type
    }
  })
  const moveSegment = createDerived(() => (from: EventTarget | null, step: number): void => {
    if (!(from instanceof HTMLElement)) return
    const all = [
      ...(from.closest('[role="group"]')?.querySelectorAll<HTMLElement>('[data-segment]') ?? []),
    ]
    all[all.indexOf(from) + step]?.focus()
  })
  const segmentKeys = createDerived(
    () =>
      (event: KeyboardEvent, segment: ReturnType<typeof fieldSegments>[number]): void => {
        if (segment.type === 'literal') return
        if (event.key === 'ArrowLeft' || event.key === 'ArrowRight') {
          event.preventDefault()
          typed.value = ''
          moveSegment.value(
            event.currentTarget,
            (event.key === 'ArrowRight') ===
              (getComputedStyle(event.currentTarget as HTMLElement).direction !== 'rtl')
              ? 1
              : -1,
          )
          return
        }
        if (event.ctrlKey || event.metaKey || event.key === 'Tab') return
        const editable = !props.disabled && !props.readOnly
        if (event.key === 'ArrowUp' || event.key === 'ArrowDown') {
          event.preventDefault()
          typed.value = ''
          if (editable)
            commit.value(
              stepSegment(
                draft.value,
                segment.type,
                event.key === 'ArrowUp' ? 1 : -1,
                fieldOptions.value,
              ),
            )
          return
        }
        if (event.key === 'Backspace' || event.key === 'Delete') {
          event.preventDefault()
          typed.value = ''
          if (!editable) return
          if (draft.value[segment.type] === undefined) moveSegment.value(event.currentTarget, -1)
          else commit.value(eraseSegment(draft.value, segment.type, fieldOptions.value))
          return
        }
        if (event.key.length !== 1) return
        event.preventDefault()
        if (editable)
          ((key: string): void => {
            const next = typeIntoSegment(
              draft.value,
              segment.type,
              typed.value,
              key,
              fieldOptions.value,
            )
            typed.value = next.typed
            commit.value(next.draft)
            if (next.advance) moveSegment.value(event.currentTarget, 1)
          })(event.key)
      },
  )
  const segmentInput = createDerived(
    () =>
      (event: Event, segment: ReturnType<typeof fieldSegments>[number]): void => {
        event.preventDefault()
        if (segment.type === 'literal' || !(!props.disabled && !props.readOnly)) return
        const data = (event as InputEvent).data ?? ''
        for (const key of data) {
          const next = typeIntoSegment(
            draft.value,
            segment.type,
            typed.value,
            key,
            fieldOptions.value,
          )
          typed.value = next.typed
          commit.value(next.draft)
          if (next.advance) {
            moveSegment.value(event.currentTarget, 1)
            break
          }
        }
      },
  )
  const effect1 = () => {
    void ((browserLanguage.value = globalThis.navigator?.language),
    props.locale === undefined &&
      (draft.value = timeDraft(props.value !== undefined ? props.value : props.defaultValue, {
        locale: props.locale ?? browserLanguage.value ?? 'en-US',
        parts: props.granularity === 'hour' ? (['hour'] as const) : (['hour', 'minute'] as const),
        hourCycle: props.hourCycle,
      })))
  }
  onMount(effect1)
  const effect2 = () => {
    void (
      props.value !== undefined &&
      (props.value !== null || current.value !== null) &&
      ((draft.value = timeDraft(props.value, fieldOptions.value)),
      (reported.value = props.value?.toString() ?? ''))
    )
  }
  watchEffect(
    createMemo(() => props.value),
    effect2,
    false,
  )
  let release3: (() => void) | undefined
  const effect3 = () => {
    release3?.()
    const ran = agentMember({
      member: 'TimeInput',
      element: () => field.value,
      state: () => ({
        value: current.value?.toString() ?? '',
        disabled: props.disabled,
        invalid: props.invalid,
        readonly: props.readOnly,
      }),
      actions: {
        set: {
          argument: 'text',
          run: (value) =>
            (() => {
              if (props.readOnly) throw new Error('The field is read-only.')
              commit.value(timeDraft(agentTime(value, props.granularity), fieldOptions.value))
            })(),
        },
        clear: () =>
          (() => {
            if (props.readOnly) throw new Error('The field is read-only.')
            commit.value({})
          })(),
      },
    })
    release3 = () => {
      ran()
    }
  }
  onMount(effect3)
  onCleanup(() => release3?.())
  return (
    <div
      class={styles.field}
      role="group"
      id={props.id}
      aria-label={props['aria-label']}
      aria-labelledby={props['aria-labelledby']}
      aria-describedby={props['aria-describedby']}
      aria-disabled={props.disabled ? 'true' : undefined}
      data-size={props.size}
      data-disabled={props.disabled ? '' : undefined}
      data-invalid={props.invalid ? '' : undefined}
      data-readonly={props.readOnly ? '' : undefined}
      data-member="time-input"
      ref={field.attach}
    >
      {/* segments */}
      <div class={styles.segments}>
        <Each of={segments.value} by={(segment, at) => `time-${segment.type}-${at}`} renew>
          {(segment) => (
            <>
              {segment.type === 'literal' ? (
                <span class={styles.separator} aria-hidden="true">
                  {segment.text}
                </span>
              ) : (
                <div
                  class={styles.segment}
                  role="spinbutton"
                  id={`${uid}-time-${segment.type}`}
                  aria-label={segmentName.value(segment.type)}
                  aria-labelledby={
                    props['aria-labelledby']
                      ? `${props['aria-labelledby']} ${uid}-time-${segment.type}`
                      : undefined
                  }
                  aria-describedby={props['aria-describedby']}
                  aria-valuenow={segment.placeholder ? undefined : segment.value}
                  aria-valuemin={segment.min}
                  aria-valuemax={segment.max}
                  aria-valuetext={segment.placeholder ? say.value.empty : segment.text}
                  aria-required={props['aria-required'] ? 'true' : undefined}
                  aria-readonly={props.readOnly ? 'true' : undefined}
                  aria-disabled={props.disabled ? 'true' : undefined}
                  aria-invalid={props.invalid ? 'true' : undefined}
                  contenteditable={!props.disabled && !props.readOnly ? 'true' : undefined}
                  inputmode={segment.type === 'dayPeriod' ? undefined : 'numeric'}
                  spellcheck="false"
                  tabindex={props.disabled ? undefined : '0'}
                  data-segment={segment.type}
                  data-placeholder={segment.placeholder ? '' : undefined}
                  data-disabled={props.disabled ? '' : undefined}
                  onfocus={() => (typed.value = '')}
                  onkeydown={($event: KeyboardEvent) => segmentKeys.value($event, itemOf(segment))}
                  onbeforeinput={($event: InputEvent) =>
                    segmentInput.value($event, itemOf(segment))
                  }
                >
                  {segment.text}
                </div>
              )}
            </>
          )}
        </Each>
      </div>
      {props.name !== undefined ? (
        <input
          type="hidden"
          name={props.name}
          value={current.value?.toString() ?? ''}
          disabled={props.disabled ? true : undefined}
        />
      ) : null}
    </div>
  )
}

TimeInput.controlKind = 'group'
